pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(address(c) != address(0));
        // Deploy an adversarial callee that reverts on any call, forcing the mutant's approve call to revert
        Reverter reverter = new Reverter();
        // On reference: transferFrom on this callee succeeds (EVM returns true for unknown call to a contract with no fallback that reverts? Actually call to contract with no matching function returns false, but low-level call returns true with false return data — the reference requires success)
        // Actually, a low-level call to a contract returns true even if the called function returns false, as long as the call doesn't revert.
        // The mutant calls approve on this reverter; if Reverter reverts on any call, both should revert — but we need the reference to succeed.
        // The reference calls transferFrom, which Reverter doesn't implement, so its fallback reverts, causing the reference to also revert. That's not the difference.
        // We need a callee where transferFrom succeeds but approve reverts.
        // So we need a contract that implements transferFrom but not approve, or that discriminates based on selector.
        // Since the bug is about selector change, we need a contract where the original selector works but the mutant selector reverts.
        // The simplest: a contract with a fallback that checks if the selector is approve and reverts, otherwise executes normally.
        // But we can't predict the selector in the contract without hardcoding? We can deploy a helper that reverts on the approve selector.
        // Given the fuzzer provides _tos and from, we deploy a minimal helper that reverts on approve and succeeds on transferFrom.
        // But the rule says the helper should embody the adversarial behavior without hardcoding the deciding value (the selector difference). Deploying a helper that explicitly checks the selector is allowed because it's constructing the adversarial environment, not hardcoding the deciding input value (like an amount or id). The deciding value here is the selector itself, which is changed in the mutant. The helper can simply revert on any unknown call, but we must ensure transferFrom succeeds. Since EOA always succeeds, we can't use an EOA because both succeed. We need a contract that implements transferFrom (so it returns true) and reverts on approve. But we can't deploy arbitrary code without adding external contracts? We can deploy a helper with a transferFrom function that returns true and a fallback that reverts.
        // That gives: reference calls transferFrom -> returns true -> call succeeds. Mutant calls approve -> no matching function -> fallback reverts -> call reverts.
        // This is allowed because we are constructing the environment, not hardcoding the fuzzed parameters.
        DiffChecker checker = new DiffChecker();
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(checker), _tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // Reference should succeed (ok == true), mutant reverts (ok == false)
        assertTrue(ok);
    }
}

// Helper that implements transferFrom (succeeding) but reverts on approve
contract DiffChecker {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    fallback() external {
        revert("Approval not supported");
    }
}

