pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        // Ensure each 'to' address is non-zero
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Deploy a helper that records the sender passed to transferFrom in its calldata
        Recorder recorder = new Recorder();
        address recorderAddr = address(recorder);
        // Start a prank as 'from' to simulate the caller being 'from'
        vm.prank(from);
        c.transfer(from, recorderAddr, _tos, v);
        // The reference contract must pass 'from' as the sender in every call; the bug passes msg.sender.
        // Since we pranked as 'from', msg.sender==from, so the bug would also pass 'from' and succeed.
        // To distinguish, we need a scenario where from != msg.sender.
        // But the call was already made with prank(from), so let's check the recorded sender.
        // However, the property we assert must be a general rule.
        // Actually, the rule is: The sender encoded in the call data must equal the 'from' argument.
        // Since we pranked as 'from', msg.sender==from, so the bug would also encode 'msg.sender' which equals 'from'.
        // To catch the bug, we must call transfer with a different caller than 'from'.
        // So we do vm.prank(someOtherCaller) but that caller is not a parameter—we can use a fixed address.
        // But the instruction says: "Take the deciding values as FUZZ PARAMETERS".
        // The deciding value is 'from' vs msg.sender. We can fuzz all parameters and have a scenario that reveals the difference.
        // Idea: Use a helper contract that is the caller, and we set msg.sender via prank to a fuzzed address.
        // But the caller address is not a parameter of transfer; it's the address of the test contract or a prank.
        // We can fuzz a separate address 'caller' and use vm.prank(caller) to call transfer.
        // Then the rule: the encoded sender must be the 'from' argument, regardless of msg.sender.
        // If from != caller, the reference uses 'from', the bug uses 'caller' (msg.sender).
        // The recorder captures the first encoded address argument of transferFrom.
        // So we assert that recorder.senderCaptured() equals 'from'.
        // But we already made the call with prank(from). We need to redo with a fuzzed caller.
        // Let's adjust: fuzz 'from', 'caddress' (which will be recorder), '_tos', 'v', and also a separate 'caller' address.
        // We'll do vm.prank(caller); c.transfer(from, recorder, _tos, v);
        // Then assert recorder.senderCaptured() == from.
        // The bug will break when caller != from, because it encodes msg.sender (caller) instead of from.
        // However, the fuzzer cannot provide a 'caller' that is a contract with code; but vm.prank sets msg.sender to an address, which can be any address.
        // That's fine; the low-level call from C to Recorder doesn't depend on the caller being a contract; it just uses whatever is pranked.
    }
}

contract Recorder {
    address public senderCaptured;
    // transferFrom(address sender, address recipient, uint256 amount)
    function transferFrom(address sender, address, uint256) external returns (bool) {
        senderCaptured = sender;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory tos, uint v) public {
        // Keep `from` different from the caller (this contract), and require non-empty array
        vm.assume(from != address(this));
        vm.assume(tos.length > 0);
        // Deploy an adversarial helper that reverts if the first encoded argument is not `from`
        ArgChecker checker = new ArgChecker(from);
        // The correct contract passes `from`, the mutant passes msg.sender -> revert
        bool ok;
        try c.transfer(from, address(checker), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract ArgChecker {
    address immutable expectedFrom;
    constructor(address _expectedFrom) { expectedFrom = _expectedFrom; }
    fallback(bytes calldata data) external payable returns (bytes memory) {
        address decodedFrom = abi.decode(data[4:], (address));
        require(decodedFrom == expectedFrom, "wrong from");
        return "";
    }
}
